/* Persistent agent conversation concept. No inference or external effects. */
const supervisorSession={open:false,scope:'run',messages:{run:[],factory:[]}};
const supervisorButton=document.createElement('button');
supervisorButton.className='supervisor-launcher';supervisorButton.id='supervisor-launcher';
supervisorButton.innerHTML='<span class="dot"></span>Supervisor <span class="muted">↗</span>';
supervisorButton.setAttribute('aria-controls','supervisor-conversation');supervisorButton.setAttribute('aria-expanded','false');
document.body.append(supervisorButton);
const supervisorDrawer=document.createElement('aside');supervisorDrawer.id='supervisor-conversation';supervisorDrawer.className='supervisor-drawer';supervisorDrawer.setAttribute('aria-label','Supervisor conversation');supervisorDrawer.hidden=true;document.body.append(supervisorDrawer);
function renderSupervisor(){supervisorDrawer.hidden=!supervisorSession.open;supervisorButton.setAttribute('aria-expanded',String(supervisorSession.open));if(!supervisorSession.open)return;
supervisorDrawer.innerHTML=`<header class="section-head"><div><span class="eyebrow">ALWAYS AVAILABLE AGENT</span><h2>Supervisor</h2></div><button id="close-supervisor" aria-label="Close supervisor">×</button></header><p>Discuss the factory or a specific run. Paused execution does not close this conversation.</p><label class="field">Conversation context<select id="supervisor-scope"><option value="run" ${supervisorSession.scope==='run'?'selected':''}>Run 042 · checkout-service</option><option value="factory" ${supervisorSession.scope==='factory'?'selected':''}>Factory · operator conversation</option></select></label><div class="notice" style="margin-top:16px">Synthetic conversation. No model is connected to this mockup.</div><div class="supervisor-transcript" aria-live="polite"><div class="message"><strong>Supervisor · example introduction</strong><p>${supervisorSession.scope==='run'?'Verification attempt 2 is active. The first check failed and triggered a repair. You can ask about evidence, flag a concern or request a control action.':'I coordinate the specialists and help you inspect readiness, permissions and blocked work. Choose a run for execution-specific questions.'}</p></div>${supervisorSession.messages[supervisorSession.scope].map(m=>`<div class="message"><strong>${m.from}</strong><p>${escape(m.text)}</p></div>`).join('')}</div><form id="supervisor-form"><label class="field">Message to supervisor<textarea id="supervisor-message" rows="3" placeholder="Watch out: preserve the existing public API…" required ${state.scenario==='offline'?'disabled':''}></textarea></label><div class="actions" style="margin-top:12px"><button class="primary" ${state.scenario==='offline'?'disabled':''}>Send message</button><button type="button" id="supervisor-hitl" ${supervisorSession.scope==='run'?'':'disabled'}>Preview HITL</button></div></form><p class="footer-note">An operator message is not automatically a scope change or permission grant. Control requests need a recorded command outcome.</p>`;}
supervisorButton.addEventListener('click',()=>{supervisorSession.open=!supervisorSession.open;renderSupervisor();if(supervisorSession.open)document.getElementById('supervisor-message').focus();});
document.addEventListener('click',event=>{if(event.target.closest('#close-supervisor')){supervisorSession.open=false;renderSupervisor();supervisorButton.focus();}if(event.target.closest('#supervisor-hitl')){state.run='waiting_input';location.hash='runs';render();renderSupervisor();toast('Synthetic HITL: a decision is required for run 042. The supervisor conversation remains available.');}});
document.addEventListener('change',event=>{if(event.target.id==='supervisor-scope'){supervisorSession.scope=event.target.value;renderSupervisor();}if(event.target.id==='scenario')renderSupervisor();});
document.addEventListener('submit',event=>{if(event.target.id!=='supervisor-form')return;event.preventDefault();if(state.scenario==='offline')return;const input=document.getElementById('supervisor-message');const text=input.value.trim();if(!text)return;supervisorSession.messages[supervisorSession.scope].push({from:'Operator',text},{from:'Message receipt · demo',text:'Message recorded in this example conversation. Awaiting a supervisor response; no run state or permission has changed.'});renderSupervisor();document.getElementById('supervisor-message').focus();});
